import{_ as t,l as n,o as a,c as l,v as i,p as s,x as o,d,i as _,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"io_uring","description":"","frontmatter":{"title":"io_uring","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/io-uring.md","filePath":"cs/io-uring.md","lastUpdated":1789023840000}'),p={name:"cs/io-uring.md"};function u(f,e,h,E,m,g){const r=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=i('<h1 id="io-uring" tabindex="-1">io_uring <a class="header-anchor" href="#io-uring" aria-label="Permalink to &quot;io_uring&quot;">​</a></h1><div class="epigraph"><p>用户与内核共享提交队列和完成队列：一次陷入可提交多条 I/O，完成不必为每个请求再进系统调用。</p><footer>—— 据 Axboe, Efficient IO with io_uring, 2019；Linux io_uring 文档整理</footer></div><p><a href="/cs/epoll">上一课</a> 仍是「就绪再 read」，每次读写一条系统调用。<a href="/cs/blk-mq">blk-mq</a> 已能并行提交块请求。缺口是把提交与完成做成<strong>环形缓冲</strong>：程序把 SQE 写进共享页，内核写 CQE。本课讲机制与和 epoll 的分工，不发明 arXiv 编号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高 IOPS 时，陷入与 <code>copy_from_user</code> 成为主成本。aio 接口历史上限制多、完成模型别扭。io_uring：mmap 两圈队列，可选 <code>IORING_SETUP_SQPOLL</code> 用内核线程轮询提交（权衡 CPU）。缺口不是重做 bio，而是用户可见的队列与一次 <code>io_uring_enter</code> 的批处理。文件、套接字、稍后的超时都可成为 op。</p><p><span class="marginnote">固定文件与固定缓冲减少每次把 fd/地址翻译进内核的开销。完成顺序不必等于提交顺序。本课不写利用错误注册缓冲的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>io_uring_setup</code> 得到 fd 与映射地址。用户填 SQE（操作码、fd、缓冲、偏移）。内核取出执行，结果进 CQE（结果码、用户 data）。程序可以 epoll 这个 uring fd，或再 enter 等待完成。块设备路径最终仍可走 bio；本课不重画 DMA。</p>',8)),(a(),s(c,null,{default:o(()=>[_(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQ%5B%22%E7%94%A8%E6%88%B7%E5%86%99%20SQE%22%5D%20--%3E%20ENT%5B%22enter%20%E6%88%96%20SQPOLL%22%5D%0A%20%20ENT%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E6%89%A7%E8%A1%8C%22%5D%0A%20%20K%20--%3E%20CQ%5B%22%E5%86%85%E6%A0%B8%E5%86%99%20CQE%22%5D%0A%20%20CQ%20--%3E%20APP%5B%22%E7%94%A8%E6%88%B7%E6%94%B6%E5%89%B2%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>io_uring 把系统调用路径从「每请求一次」改成「每批一次」，并让完成与提交解耦，便于流水线。它不取消 <a href="/cs/vfs">VFS</a> 与权限检查：每个 op 仍以发出进程的身份执行。与共享内存 IPC 不同：这里共享的是请求描述，不是业务文件内容本身（除非 op 指向共享缓冲）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 opcode 列成表。不保证旧内核有 uring。下一课离开事件 I/O，进入内核如何数时间：滴答与 jiffies——超时与调度一直在用，尚未当课。</p><p>后课默认：I/O 可批量异步完成。内核的滴答计数与 HZ，下一课 jiffies。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>io_uring 用共享 SQ/CQ 批量提交与收割 I/O。</li><li>仍走 VFS 权限；底层可接 bio。</li><li>内核时间基准是 jiffies 的缺口。</li><li>出处：Axboe, <em>Efficient IO with io_uring</em>（2019）；Linux <code>io_uring</code> 文档。</li></ul>',7))])}const b=t(p,[["render",u]]);export{S as __pageData,b as default};
